test('organisations : fichier entier inchangé hors présentation du seul tableau, mêmes conditions de confidentialité',()=>{const p=path.join(root,'outils/audits/I18N-TABLEAU-ORGANISATIONS-871-preuve.json'),proof=fs.existsSync(p)?JSON.parse(fs.readFileSync(p)):null,at=f=>proof?execFileSync('git',['show',proof.codeCommit+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6}):read(f);assert.deepEqual(clean(parse(at('plateau-organisations-quetes.js'))),clean(parse(old('plateau-organisations-quetes.js'))));assert.equal(at('plateau.html').replace('plateau-organisations-quetes.js?v=tableau-organisations-871-','plateau-organisations-quetes.js?v=').replace('\n<script src="i18n/organization-directory-resources.js?v=20261114"></script>',''),old('plateau.html'));if(proof)assert.equal(execFileSync('git',['diff','--name-only',base,proof.codeCommit,'--','api','migrations','supabase','supabase.js','auth.js','data.js','plateau-politique.js','plateau-core.js','plateau-pnj.js','plateau-contact-organisation.js','plateau-equipements-collectifs.js','i18n/plateau-init.js','i18n/i18n-init.js','style.css'],{cwd:root,encoding:'utf8'}),'');});
test('organisations : quinze français exacts, neuf types canoniques, neuf langues et espaces du français conservés',()=>{const c=resources(read('i18n/organization-directory-resources.js')),rows=manifest.rows;assert.equal(rows.length,15);assert.deepEqual(c.fr.translation.organizationDirectory,Object.fromEntries(rows));let count=0;for(const n of parse(old('data.js')).body)if(n.type==='VariableDeclaration')for(const d of n.declarations)if(d.id.name==='TYPES_ORGANISATIONS')for(const p of d.init.properties){const label=p.value.properties?.find(p=>p.key.name==='label');if(label){assert.equal(c.fr.translation.organizationDirectory['type_'+p.key.name],label.value.value);count++;}}assert.equal(count,9);for(const lang of Object.keys(c)){const words=c[lang].translation.organizationDirectory;assert.deepEqual(Object.keys(words),rows.map(r=>r[0]));for(const [key,fr]of rows){assert.ok(words[key].trim());assert.ok(!words[key].includes('{{'));if(lang!=='fr')assert.notEqual(words[key],fr);}}});
